#!/bin/bash
# Cinammon WebHost · instalación (todo propio: no descarga nada de terceros salvo WordPress/Git si los pides)
set -e
mkdir -p /mnt/server && cd /mnt/server
apt-get update -qq >/dev/null && apt-get install -y -qq git wget ca-certificates >/dev/null

# Configuración de nginx y PHP-FPM. Si existía una configuración ajena se guarda como .old;
# si ya es la de Cinammon se respeta (por si la has personalizado).
install_config() {
    if [[ -d nginx || -d php-fpm ]] && ! grep -q "Cinammon WebHost" nginx/nginx.conf 2>/dev/null; then
        echo "▸ Sustituyendo la configuración anterior (copia en nginx.old/ y php-fpm.old/)…"
        rm -rf nginx.old php-fpm.old
        [[ -d nginx ]] && mv nginx nginx.old
        [[ -d php-fpm ]] && mv php-fpm php-fpm.old
    fi
    mkdir -p nginx/conf.d php-fpm webroot tmp logs
    [[ -f nginx/nginx.conf ]] || cat > nginx/nginx.conf <<'CIN_NGINX_CONF_EOF'
# Cinammon WebHost · nginx (sin root: todo vive en /home/container)
worker_processes auto;
pid /home/container/tmp/nginx.pid;
error_log /home/container/logs/nginx-error.log warn;
daemon off;

events {
    worker_connections 1024;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    access_log /home/container/logs/nginx-access.log;
    client_body_temp_path /home/container/tmp/client_body;
    proxy_temp_path /home/container/tmp/proxy;
    fastcgi_temp_path /home/container/tmp/fastcgi;
    uwsgi_temp_path /home/container/tmp/uwsgi;
    scgi_temp_path /home/container/tmp/scgi;

    sendfile on;
    tcp_nopush on;
    keepalive_timeout 65;
    server_tokens off;
    client_max_body_size 100m;

    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_types text/plain text/css application/json application/javascript text/xml application/xml image/svg+xml;

    include /home/container/nginx/conf.d/*.conf;
}
CIN_NGINX_CONF_EOF
    [[ -f nginx/conf.d/default.conf ]] || cat > nginx/conf.d/default.conf <<'CIN_SITE_CONF_EOF'
# Cinammon WebHost · sitio por defecto (Wings ajusta el puerto al arrancar)
server {
    listen 8080;
    server_name _;

    root /home/container/webroot;
    index index.php index.html index.htm;
    charset utf-8;

    add_header X-Content-Type-Options nosniff always;
    add_header X-Frame-Options SAMEORIGIN always;
    add_header Referrer-Policy strict-origin-when-cross-origin always;

    location / {
        try_files $uri $uri/ /index.php?$query_string;
    }

    location = /favicon.ico { access_log off; log_not_found off; }
    location = /robots.txt  { access_log off; log_not_found off; }

    location ~ \.php$ {
        try_files $uri =404;
        fastcgi_split_path_info ^(.+\.php)(/.+)$;
        fastcgi_pass unix:/home/container/tmp/php-fpm.sock;
        fastcgi_index index.php;
        include /etc/nginx/fastcgi_params;
        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
        fastcgi_param PATH_INFO $fastcgi_path_info;
        fastcgi_param HTTP_PROXY "";
        fastcgi_read_timeout 300;
    }

    # Archivos ocultos (.git, .env, .htaccess…)
    location ~ /\.(?!well-known) {
        deny all;
    }
}
CIN_SITE_CONF_EOF
    [[ -f php-fpm/php-fpm.conf ]] || cat > php-fpm/php-fpm.conf <<'CIN_FPM_CONF_EOF'
; Cinammon WebHost · PHP-FPM (sin root)
[global]
pid = /home/container/tmp/php-fpm.pid
error_log = /home/container/logs/php-fpm.log
daemonize = yes

[www]
listen = /home/container/tmp/php-fpm.sock
listen.mode = 0660
pm = dynamic
pm.max_children = 10
pm.start_servers = 2
pm.min_spare_servers = 1
pm.max_spare_servers = 4
pm.max_requests = 500
clear_env = no
catch_workers_output = yes

; Ajustes de PHP (puedes cambiarlos aquí)
php_admin_value[error_log] = /home/container/logs/php-error.log
php_admin_flag[log_errors] = on
php_value[upload_max_filesize] = 100M
php_value[post_max_size] = 100M
php_value[memory_limit] = 256M
php_value[max_execution_time] = 300
php_value[date.timezone] = Europe/Madrid
CIN_FPM_CONF_EOF
}

echo "▸ Configurando Nginx + PHP-FPM…"
install_config
rm -f start.sh
cat > start.sh <<'CIN_START_EOF'
#!/bin/ash
# Cinammon WebHost · arranque de PHP-FPM + Nginx
P='\033[1;35m'; C='\033[1;36m'; G='\033[0;32m'; Y='\033[1;33m'; R='\033[0;31m'; D='\033[2m'; N='\033[0m'
ok()   { echo -e "${G}  ✔ $1${N}"; }
warn() { echo -e "${Y}  ⚠ $1${N}"; }
fail() { echo -e "${R}  ✖ $1${N}"; }

echo -e "${P}"
echo -e "   ╔═════════════════════════════════════╗"
echo -e "   ║     ${C}C I N A M M O N${P}  ·  WEBHOST     ║"
echo -e "   ╚═════════════════════════════════════╝${N}"
echo -e "${D}   Nginx + PHP $(php -r 'echo PHP_VERSION;' 2>/dev/null)${N}\n"

echo -e "${C}▸ Limpiando temporales…${N}"
mkdir -p /home/container/tmp /home/container/logs
rm -rf /home/container/tmp/* && mkdir -p /home/container/tmp/client_body && ok "Temporales limpios" || warn "No se pudieron limpiar los temporales"

if [ ! -f /home/container/webroot/index.php ] && [ ! -f /home/container/webroot/index.html ]; then
    warn "webroot/ no tiene index.php ni index.html: sube tu web desde Archivos o por SFTP."
fi

echo -e "${C}▸ Iniciando PHP-FPM…${N}"
if /usr/sbin/php-fpm --fpm-config /home/container/php-fpm/php-fpm.conf --daemonize; then
    ok "PHP-FPM en marcha"
else
    fail "PHP-FPM no arrancó. Revisa php-fpm/php-fpm.conf"
    exit 1
fi

echo -e "${C}▸ Iniciando Nginx…${N}"
if /usr/sbin/nginx -t -c /home/container/nginx/nginx.conf -p /home/container/ >/dev/null 2>&1; then
    ok "Configuración de Nginx correcta"
else
    fail "Error en la configuración de Nginx:"
    /usr/sbin/nginx -t -c /home/container/nginx/nginx.conf -p /home/container/
    exit 1
fi

echo -e "\n${G}  ● Web en línea${N}  ${C}http://${SERVER_IP:-tu-ip}:${SERVER_PORT:-puerto}${N}"
echo -e "${D}    Archivos de la web: webroot/   ·   Registros: logs/${N}\n"
exec /usr/sbin/nginx -c /home/container/nginx/nginx.conf -p /home/container/
CIN_START_EOF
chmod +x start.sh

cd /mnt/server/webroot
put_welcome() {
cat > /mnt/server/webroot/index.php <<'CIN_INDEX_EOF'
<?php
$site = htmlspecialchars(getenv('SITE_NAME') ?: 'Mi web en Cinammon', ENT_QUOTES, 'UTF-8');
$php = PHP_VERSION;
$port = htmlspecialchars($_SERVER['SERVER_PORT'] ?? '', ENT_QUOTES, 'UTF-8');
?><!doctype html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title><?= $site ?> · Cinammon WebHost</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Orbitron:wght@500;700;900&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
<style>
:root{--bg:#04060d;--card:#0a0e1c;--line:rgba(255,255,255,.08);--text:#e2e8f0;--muted:#94a3b8;--pink:#ff2d95;--cyan:#00f7ff;--violet:#a855f7}
*{box-sizing:border-box}html,body{margin:0}
body{min-height:100vh;background:var(--bg);color:var(--text);font-family:Inter,system-ui,sans-serif;display:flex;align-items:center;justify-content:center;padding:32px 16px;overflow-x:hidden}
body:before{content:"";position:fixed;inset:0;background:radial-gradient(600px 400px at 15% 10%,rgba(0,247,255,.12),transparent 60%),radial-gradient(600px 400px at 85% 90%,rgba(255,45,149,.12),transparent 60%),radial-gradient(circle,rgba(255,255,255,.07) 1px,transparent 1px) 0 0/24px 24px;pointer-events:none}
.wrap{position:relative;width:100%;max-width:760px}
.top{height:1px;background:linear-gradient(90deg,transparent,var(--pink),var(--cyan),transparent);margin-bottom:28px}
.badge{display:inline-flex;align-items:center;gap:8px;border:1px solid rgba(0,247,255,.35);background:rgba(0,247,255,.08);color:var(--cyan);border-radius:999px;padding:6px 14px;font:600 11px Orbitron,sans-serif;letter-spacing:.18em;text-transform:uppercase}
.dot{width:8px;height:8px;border-radius:50%;background:#34d399;box-shadow:0 0 10px #34d399;animation:p 1.6s infinite}@keyframes p{50%{opacity:.35}}
h1{font:900 clamp(28px,6vw,46px)/1.1 Orbitron,sans-serif;margin:18px 0 10px;letter-spacing:.02em}
h1 span{background:linear-gradient(90deg,var(--pink),var(--violet),var(--cyan));-webkit-background-clip:text;background-clip:text;color:transparent}
.lead{color:var(--muted);font-size:16px;line-height:1.6;margin:0 0 28px}
.grid{display:grid;gap:14px;grid-template-columns:repeat(auto-fit,minmax(210px,1fr))}
.card{background:linear-gradient(180deg,rgba(255,255,255,.035),rgba(255,255,255,.01));border:1px solid var(--line);border-radius:16px;padding:18px;transition:border-color .2s,transform .2s}
.card:hover{border-color:rgba(255,45,149,.45);transform:translateY(-2px)}
.n{font:700 12px Orbitron,sans-serif;color:var(--pink);letter-spacing:.15em}
.card h2{font:700 15px Orbitron,sans-serif;margin:8px 0 6px}
.card p{margin:0;color:var(--muted);font-size:13.5px;line-height:1.55}
code{font:500 12.5px ui-monospace,Menlo,monospace;color:var(--cyan);background:rgba(0,247,255,.08);border:1px solid rgba(0,247,255,.2);border-radius:6px;padding:1px 6px}
.stats{display:flex;flex-wrap:wrap;gap:10px;margin:26px 0}
.stat{border:1px solid var(--line);background:var(--card);border-radius:12px;padding:10px 14px;font-size:12px;color:var(--muted)}
.stat b{display:block;color:var(--text);font:700 14px Orbitron,sans-serif;margin-top:2px}
.cta{display:inline-flex;align-items:center;gap:8px;text-decoration:none;font:700 13px Orbitron,sans-serif;color:#fff;background:linear-gradient(90deg,var(--pink),#c026d3);border-radius:12px;padding:12px 20px;box-shadow:0 0 22px rgba(255,45,149,.35)}
.cta.alt{background:transparent;border:1px solid rgba(0,247,255,.45);color:var(--cyan);box-shadow:none}
.actions{display:flex;flex-wrap:wrap;gap:12px}
footer{margin-top:34px;color:#64748b;font-size:12px}
footer a{color:var(--muted)}
</style>
</head>
<body>
<main class="wrap">
  <div class="top"></div>
  <span class="badge"><span class="dot"></span> Online · Cinammon WebHost</span>
  <h1><?= $site ?><br><span>ya está en línea</span></h1>
  <p class="lead">Tu servidor web (Nginx + PHP) funciona. Esta es la página de bienvenida: sustitúyela por tu web siguiendo uno de estos caminos.</p>

  <div class="grid">
    <div class="card"><div class="n">01</div><h2>Sube tus archivos</h2><p>En el panel: <b>Archivos</b> → carpeta <code>webroot/</code>. O por SFTP (puerto <code>2022</code>) con los datos de <b>Acceso SFTP</b>. Borra este <code>index.php</code>.</p></div>
    <div class="card"><div class="n">02</div><h2>Instala una app</h2><p>En el panel abre <b>Aplicaciones</b>: WordPress y otras apps en un clic, con su base de datos creada sola. Sin terminal.</p></div>
    <div class="card"><div class="n">03</div><h2>Despliega con Git</h2><p>Pon la URL de tu repositorio en <code>Repositorio Git</code> y reinstala. Para repos privados, añade usuario y token.</p></div>
  </div>

  <div class="stats">
    <div class="stat">PHP<b><?= htmlspecialchars($php, ENT_QUOTES, 'UTF-8') ?></b></div>
    <div class="stat">Servidor<b>Nginx</b></div>
    <?php if ($port): ?><div class="stat">Puerto<b><?= $port ?></b></div><?php endif; ?>
    <div class="stat">Subida máx.<b>100 MB</b></div>
  </div>

  <div class="actions">
    <a class="cta" href="https://panel.cinammon.net/servers" target="_blank" rel="noopener">Abrir mi panel →</a>
    <a class="cta alt" href="https://store.cinammon.net/store/web" target="_blank" rel="noopener">Ampliar mi plan</a>
  </div>

  <footer>Alojado en <a href="https://cinammon.net" target="_blank" rel="noopener">Cinammon Network</a> · Infraestructura cloud para comunidades.</footer>
</main>
</body>
</html>
CIN_INDEX_EOF
}
is_welcome() { [[ -f index.php ]] && grep -q -E 'Cinammon WebHost|Berny WebHost' index.php; }
# WordPress instalado por este egg pero nunca configurado (sin wp-config.php): se puede retirar sin perder nada.
is_unused_wp() { [[ -f wp-settings.php && -d wp-includes && ! -f wp-config.php ]]; }
remove_unused_wp() {
    rm -rf wp-admin wp-includes wp-content
    rm -f index.php license.txt readme.html xmlrpc.php wp-*.php
}

if [[ "${WORDPRESS}" == "true" || "${WORDPRESS}" == "1" ]]; then
    if [[ -f wp-config.php || -f wp-config-sample.php ]]; then
        echo "✔ WordPress ya estaba instalado: no se toca."
    else
        echo "▸ Instalando WordPress en español…"
        # Se trabaja en el disco del servidor: el /tmp del instalador es muy pequeño.
        WPTMP=/mnt/server/tmp/wp-install
        rm -rf "$WPTMP" && mkdir -p "$WPTMP"
        if { wget -q https://es.wordpress.org/latest-es_ES.tar.gz -O "$WPTMP/wp.tar.gz" || wget -q https://wordpress.org/latest.tar.gz -O "$WPTMP/wp.tar.gz"; } \
           && tar xzf "$WPTMP/wp.tar.gz" -C "$WPTMP" && [[ -f "$WPTMP/wordpress/wp-settings.php" ]]; then
            is_welcome && rm -f index.php
            cp -r "$WPTMP/wordpress/." .
            rm -rf "$WPTMP"
            echo "✔ WordPress instalado: abre tu web para terminar (crea antes una base de datos en el panel)."
        else
            rm -rf "$WPTMP"
            echo "✖ No se pudo descargar o descomprimir WordPress (¿sin espacio en disco o sin conexión?). Se deja la página de bienvenida."
            [[ -z "$(ls -A .)" ]] && put_welcome
        fi
    fi
elif [[ "${USER_UPLOAD}" == "true" || "${USER_UPLOAD}" == "1" ]]; then
    echo "✔ Modo «solo mis archivos»: webroot/ no se modifica."
elif [[ -n "${GIT_ADDRESS}" ]]; then
    [[ ${GIT_ADDRESS} != *.git ]] && GIT_ADDRESS=${GIT_ADDRESS}.git
    if [[ -n "${USERNAME}" && -n "${ACCESS_TOKEN}" ]]; then
        GIT_ADDRESS="https://${USERNAME}:${ACCESS_TOKEN}@$(echo ${GIT_ADDRESS} | cut -d/ -f3-)"
    fi
    if [[ -d .git ]]; then
        echo "▸ Actualizando el repositorio…"; git pull
    elif [[ -z "$(ls -A .)" ]] || { is_welcome && [[ $(ls -A | wc -l) -eq 1 ]]; } || is_unused_wp; then
        is_unused_wp && remove_unused_wp
        rm -f index.php
        echo "▸ Clonando el repositorio…"
        if [[ -z "${BRANCH}" ]]; then git clone ${GIT_ADDRESS} .; else git clone --single-branch --branch ${BRANCH} ${GIT_ADDRESS} .; fi
    else
        echo "⚠ webroot/ ya tiene archivos y no es un repositorio Git: no se clona para no borrar nada."
    fi
else
    if is_unused_wp; then
        echo "▸ «Instalar WordPress» está desactivado y WordPress nunca se configuró: se retira."
        remove_unused_wp
    elif [[ -f wp-config.php ]]; then
        echo "⚠ Hay un WordPress configurado en webroot/: no se borra para no perder tu web."
        echo "  Si quieres quitarlo, borra el contenido de webroot/ desde Archivos y vuelve a reinstalar."
    fi
    if [[ -z "$(ls -A .)" ]] || is_welcome; then
        put_welcome; echo "✔ Página de bienvenida de Cinammon lista en webroot/index.php"
    else
        echo "✔ webroot/ ya tiene tu web: no se modifica."
    fi
fi

chown -R 1000:1000 /mnt/server 2>/dev/null || true
echo "✔ Instalación completada"
